script:
frappe.ui.form.on("Quotation", {
	refresh(frm) {
		if (frm.doc.docstatus === 1) {
		    // no need to add the the button
            return;
		}

        frm.add_custom_button("Load Items from Lead", function() {
            if (frm.doc.custom_originating_lead) {
                frm.clear_table('items');
                frappe.model.with_doc('CY Lead', frm.doc.custom_originating_lead, function () {
                    let source_doc = frappe.model.get_doc('CY Lead', frm.doc.custom_originating_lead);

                    if (source_doc.customer) {
                        frm.doc.party_name = source_doc.customer;
                        frm.refresh_field('party_name');
                    }
                    $.each(source_doc.services_required, function (index, source_row) {
                        target_row = frm.add_child('items');
                        target_row.item_code = source_row.item_code;
                        target_row.item_name = source_row.item_name;
                        target_row.qty = source_row.qty;
                        target_row.uom = "Day";
                        target_row.rate = source_row.rate;
                        target_row.amount = target_row.qty * target_row.rate;
                        frm.refresh_field('items');
                    });
                });
            }
            else {
                frappe.msgprint("Select 'Originating Lead' first");
            }
        })
	}
});
